# ---------------------------------------------------------------- face bones and weights on the new head
def from_generated(co):
    """For a point of the new head: the generated surface's class and point in head_input.png nearest it."""
    loc, _, fi, _ = GEN_BVH.find_nearest(co, 0.05)
    if fi is None:
        return head_shape.SKIN, None
    c, uvs, pts = GEN_FACES[fi]
    w = poly_3d_calc(pts, loc)
    u = sum((uv * x for uv, x in zip(uvs, w)), Vector((0, 0)))
    return c, (u.x * 1024, (1 - u.y) * 1024)


hb = bmesh.new(); hb.from_mesh(head.data)
hb.verts.ensure_lookup_table()
hb.normal_update()
HIMG, HCLS = {}, {}
for v in hb.verts:
    HCLS[v], HIMG[v] = from_generated(v.co)
    if HIMG[v] is None:
        HIMG[v] = (-1e4, -1e4)


# The opening each eye takes: its own, as the picture painted it (the head is the generated one, not mirrored: an
# opening mirrored over from the other eye missed the right eye's own by up to 1.2 cm - the ball stood out of the lids
# and the lids round it were lifted 6 mm).
EYE_FROM = {'l': 'l', 'r': 'r'}
_EIMG = {}


def eye_img(v, s):
    """Where in head_input.png vertex v lies for eye s's outline: its own place, or its mirror image's for an eye
    that takes the other's opening."""
    if EYE_FROM[s] == s:
        return HIMG[v]
    if v not in _EIMG:
        q = from_generated(mirror(v.co))[1]
        _EIMG[v] = q if q is not None else (-1e4, -1e4)
    return _EIMG[v]


def lid_weight(v, s):
    """Upper lid weight for a blink of BLINK_DEG: rim to rim it grades so every point lands on the lower rim."""
    e, src = EYE[s], EYE[EYE_FROM[s]]
    if v.normal.dot(FWD) <= 0.3:
        return 0.0
    x, y = eye_img(v, s)
    up, lo = EYE_RIMS[EYE_FROM[s]]['upper'], EYE_RIMS[EYE_FROM[s]]['lower']
    if not src['x0'] <= x <= src['x1']:
        return 0.0
    yu, yl = interp(up, x), interp(lo, x)
    scale = e['deg'] / BLINK_DEG  # the narrower eye turns less
    if y > yl:
        return 0.0
    if y >= yu:
        return (yl - y) / src['omax'] * scale
    return (yl - yu) / src['omax'] * scale * (1 - smoothstep(yu - y, 0, LID_FADE))


def jaw_weight(v):
    """None: MPFB's jaw weight stays. 0: no jaw (above the lip line, the moustache). Else at least this much: the
    lower lip just under the line fully, fading out down to JAW_FULL px."""
    if HCLS[v] == head_shape.HAIR and v.co.z > MOUTH_C.z - 0.02 and v.normal.dot(FWD) > 0.3:
        return 0.0
    s = lip_s(v, HIMG)
    if s is None:
        return None
    return 0.0 if s <= 0.5 else 1 - smoothstep(s, JAW_FULL * 0.5, JAW_FULL)


def hair_detail():
    """Strands on the hair, whiskers and moustache (the generated texture is smoothed into a flat mass): per texel the
    hair's direction - away from the crown along the surface (down and back over the head, down the whiskers) - and
    across it streaks of a few widths (clumps, strands); into the albedo (lighter and darker strands) and a normal
    map (each strand a ridge)."""
    hair_v = np.array([1.0 if HCLS[v] == head_shape.HAIR else 0.0 for v in hb.verts])
    for _ in range(2):  # soft edge round the hairline
        nb = np.array([np.mean([hair_v[e.other_vert(v).index] for e in v.link_edges]) for v in hb.verts])
        hair_v = 0.5 * hair_v + 0.5 * nb
    me = head.data
    data, cov = mat_util.raster(me, TEX, hair_v[:, None])
    p, n, hw = data[..., :3], data[..., 3:6], data[..., 6]
    n = n / np.maximum(np.linalg.norm(n, axis=-1, keepdims=True), 1e-6)
    cx = float(np.mean([v.co.x for v in hb.verts]))
    # combed from the crown down: strands run along the meridians round a vertical axis through the crown, so across
    # them the coordinate is the angle round it (times a typical radius), waving a little down their length
    phi = np.arctan2(p[..., 0] - cx, p[..., 1] - HAIR_CROWN[0])
    a = HAIR_CROWN[1] - p[..., 2]
    c = phi * 0.09 + 0.003 * np.sin(a * 70.0)
    rng = np.random.default_rng(7)
    s = np.zeros_like(c)
    for freq, amp in HAIR_STREAKS:
        ph = rng.uniform(0, 2 * np.pi)
        s += amp * np.sin(2 * np.pi * c * freq + ph + 1.5 * np.sin(2 * np.pi * a * 9 + ph))
    s /= sum(a_ for _, a_ in HAIR_STREAKS)
    img = bpy.data.images['head_albedo']
    w, hh = img.size
    px = np.array(img.pixels[:], np.float32).reshape(hh, w, 4)
    # not where the portrait itself is the texture (facing the view): its own curls are drawn there
    facing = (n * np.array(FWD, np.float32)).sum(-1)
    k = (hw * cov * (1 - np.clip((facing - PORTRAIT_FRONT[0]) / (PORTRAIT_FRONT[1] - PORTRAIT_FRONT[0]), 0, 1)))[..., None]
    # one hue for all the hair: the portrait's (the front, facing the view it was painted from); the generated back
    # came out red-brown
    rgb = px[..., :3]
    lum = np.maximum(rgb @ mat_util.LUM, 1e-4)
    chroma = rgb / lum[..., None]
    front = (hw > 0.9) & cov & (facing > 0.6)
    target = np.median(chroma[front], 0)
    chroma = chroma + (target - chroma) * (HAIR_HUE * k)
    skin = (hw < 0.5) & cov  # (the hairline too: the greenish cast sits at the temples)
    skin_hue = np.median(chroma[skin & (facing > 0.6)], 0)
    g = skin[..., None] * np.clip((chroma[..., 1:2] / np.maximum(chroma[..., 0:1], 1e-4) - SKIN_GREEN[0])
                                  / (SKIN_GREEN[1] - SKIN_GREEN[0]), 0, 1)
    chroma = chroma + (skin_hue - chroma) * g
    print('skin: %d greenish texels to the skin hue' % int((g[..., 0] > 0.5).sum()))
    rgb = chroma * lum[..., None]
    # the neck under the jaw: plain skin, darker up in the beard's shadow (projected and carried down, the picture's
    # collar and the rim's colours ran down it in stripes)
    cut = CHIN_Z - NECK_CUT
    neck = cov & (p[..., 2] < cut + 0.004) & (hw < 0.5)
    fade = np.clip((cut + 0.004 - p[..., 2]) / 0.012, 0, 1)
    sh = NECK_SHADE[1] + (NECK_SHADE[0] - NECK_SHADE[1]) * np.clip((cut - p[..., 2]) / (cut - NECK_Z0), 0, 1)
    skin_lum = float(np.median(lum[skin & (facing > 0.6)]))  # (in the picture's own encoding, like rgb)
    skin_rgb = skin_hue[None, None, :] * (skin_lum * sh)[..., None]
    rgb = np.where(neck[..., None], rgb + (skin_rgb - rgb) * fade[..., None], rgb)
    print('neck: %d texels plain skin' % int(neck.sum()))
    # under the jaw and the beard (facing down, out of the picture's view): in their shade, no paler than the skin
    # there - the picture's white shirt collar and the generation's pale beard ends were stretched over them in light
    # shards
    hair_lum = float(np.median(lum[(hw > 0.9) & cov & (facing > 0.6)]))
    under = cov & (n[..., 2] < -UNDER_JAW[0]) & (p[..., 2] < CHIN_Z + UNDER_JAW[2])
    du = np.clip((-n[..., 2] - UNDER_JAW[0]) / (UNDER_JAW[1] - UNDER_JAW[0]), 0, 1) * under
    cap = (skin_lum * (1 - hw) + hair_lum * hw) * UNDER_JAW_SHADE
    l_now = np.maximum(rgb @ mat_util.LUM, 1e-4)
    pale = np.clip(1 - (rgb.max(-1) - rgb.min(-1)) / np.maximum(rgb.max(-1), 1e-4) / 0.25, 0, 1)  # low chroma: white
    # ... and the throat under the chin whichever way it faces: the picture's shirt collar was projected onto it and
    # showed from below as a white sheet between the chin and the collar
    du = np.maximum(du, ((pale > 0.5) & cov & (p[..., 2] < CHIN_Z + UNDER_JAW[2]) & (hw < 0.5)).astype(du.dtype))
    tint = (skin_hue[None, None, :] * (1 - hw[..., None]) + target[None, None, :] * hw[..., None])
    fixed = np.where((pale > 0.5)[..., None], tint * np.minimum(l_now, cap)[..., None],
                     rgb * (np.minimum(l_now, cap) / l_now)[..., None])
    rgb = rgb + (fixed - rgb) * du[..., None]
    print('under the jaw: %d texels shaded' % int((du > 0.5).sum()))
    px[..., :3] = np.clip(rgb * (1 + HAIR_CONTRAST * s[..., None] * k), 0, 1)
    # the baked islands (and the bake's own margin) padded out over the background: no dark rims on the small ones
    px[..., :3] = mat_util.pad(px[..., :3], px[..., :3].max(-1) > 0.004)
    img.pixels.foreach_set(px.ravel()); mat_util.write(img)
    height = s * k[..., 0] * HAIR_RELIEF
    nrm = mat_util.save('Head_Normal', mat_util.normals(height) * 0.5 + 0.5, HEAD_NORMAL, 'Non-Color')
    mat_util.material('Head_Skin', img, None, nrm, rough=0.6)
    print('hair strands: %d texels' % int((hw > 0.5).sum()))


def ear_surroundings():
    """The ears cleaned in the baked texture: the generation's ear sits a little elsewhere than the portrait's and the
    bake picked between the sources face by face - flakes of hair colour on the ear's rim. Within EAR_RING[0] of the
    ear (head_ears) it is the portrait's skin a little redder (its fine light and dark kept a little), fading into
    what is there by EAR_RING[1]; those vertices count as skin (where the generation coloured them hair-dark,
    hair_detail() drew strands on the ear). The hair round the ears is left as it is."""
    kd = KDTree(len(HEAD_EAR_PTS))
    for i, q in enumerate(HEAD_EAR_PTS):
        kd.insert(q, i)
    kd.balance()
    me = head.data
    data, cov = mat_util.raster(me, TEX)
    img = bpy.data.images['head_albedo']
    w_, hh = img.size
    px = np.array(img.pixels[:], np.float32).reshape(hh, w_, 4)
    rgb = px[..., :3]
    P = data[..., :3]
    cand = np.zeros(cov.shape, bool)
    for c in EAR_C:
        cand |= cov & (np.linalg.norm(P - np.array(c[:]), axis=-1) < 0.06)
    dist = np.full(cov.shape, 1.0, np.float32)
    for y, x in zip(*np.nonzero(cand)):
        dist[y, x] = kd.find(Vector(P[y, x].tolist()))[2]
    lum = rgb @ LUM
    detail = np.clip(lum / np.maximum(blur(lum, 4), 1e-4), 0.93, 1.07)[..., None]
    ear_col = np.clip(np.array(SKIN_SRGB) * np.array(EAR_TINT), 0, 1)  # the bake there is half hair-dark
    k = np.clip(1 - (dist - EAR_RING[0]) / (EAR_RING[1] - EAR_RING[0]), 0, 1)[..., None] * cov[..., None]
    px[..., :3] = rgb * (1 - k) + np.clip(ear_col * detail, 0, 1) * k
    img.pixels.foreach_set(px.ravel()); mat_util.write(img)
    n = 0
    for hv in hb.verts:
        if kd.find(hv.co)[2] < EAR_RING[0]:
            HCLS[hv] = head_shape.SKIN
            n += 1
    print('ears: %d texels, %d vertices skin' % (int((k[..., 0] > 0.5).sum()), n))


ear_surroundings()
hair_detail()


def in_poly(pt, poly):
    x, y = pt
    inside = False
    for (x1, y1), (x2, y2) in zip(poly, poly[1:] + poly[:1]):
        if (y1 > y) != (y2 > y) and x < (x2 - x1) * (y - y1) / (y2 - y1 + 1e-12) + x1:
            inside = not inside
    return inside


def edge_dist(pt, poly):
    best = 1e9
    p = Vector(pt)
    for a, b in zip(poly, poly[1:] + poly[:1]):
        a, b = Vector(a), Vector(b)
        ab = b - a
        t = max(0.0, min(1.0, (p - a).dot(ab) / max(ab.dot(ab), 1e-9)))
        best = min(best, (p - (a + ab * t)).length)
    return best


EYE_POLY = {s: r['upper'] + r['lower'][::-1][1:-1] for s, r in EYE_RIMS.items()}


def fit_eyes():
    """An eyeball per eye fitted to the opening: the rim (where the outline EYE_RIMS crosses the head's edges, in the
    portrait's picture) lies on a sphere of the opening's half-width (EYE_R) round a centre behind it - the lids wrap
    it as real ones do. Then the surface inside the opening sinks EYE_IN into the sphere and the lids round it stay
    EYE_OUT outside: from any side the eyeball shows exactly inside the rim, the lids cover the rest of it (a ball
    put behind the painted eye's middle poked out in front of the lids and left the painted eye showing beside it).
    The centre is the lids' blink pivot and the eye bone's head."""
    me = head.data
    for s_ in EYE_POLY:
        e = EYE[s_]
        poly = EYE_POLY[EYE_FROM[s_]]
        near = [hv for hv in hb.verts if (hv.co - e['pivot']).length < 0.035 and hv.normal.dot(FWD) > -0.2]
        ins = {hv for hv in near if in_poly(eye_img(hv, s_), poly)}
        rim, edge_of = [], {}
        for hv in ins:
            for ed in hv.link_edges:
                o = ed.other_vert(hv)
                if o not in ins:
                    da, db = edge_dist(eye_img(hv, s_), poly), edge_dist(eye_img(o, s_), poly)
                    rim.append(hv.co.lerp(o.co, da / max(da + db, 1e-9)))
                    edge_of.setdefault(hv, []).append(rim[-1])
        P = np.array([q[:] for q in rim])
        cen = P.mean(0)
        fw = np.array(FWD[:])
        lat = P - cen - np.outer((P - cen) @ fw, fw)
        R = float(np.clip(np.linalg.norm(lat, axis=1).max(), *EYE_R))
        c = cen - fw * math.sqrt(max(R * R - float((np.linalg.norm(lat, axis=1) ** 2).mean()), (0.5 * R) ** 2))
        for _ in range(40):  # Gauss-Newton: the rim's distances from c as near R as they go
            d = P - c
            L = np.linalg.norm(d, axis=1)
            J = -d / L[:, None]
            dc = np.linalg.lstsq(J, -(L - R), rcond=None)[0]
            c = c + dc
            if np.linalg.norm(dc) < 1e-7:
                break
        L = np.linalg.norm(P - c, axis=1)
        c = Vector(c.tolist())
        sunk = lifted = 0
        worst = 0.0
        for hv in near:
            v = me.vertices[hv.index]
            d = v.co - c
            r = d.length
            if r < 1e-6:
                continue
            if hv in ins and r > R - EYE_IN:
                v.co = c + d * ((R - EYE_IN) / r); sunk += 1
            elif hv not in ins and r < R + EYE_OUT:
                worst = max(worst, R + EYE_OUT - r)
                v.co = c + d * ((R + EYE_OUT) / r); lifted += 1
        for hv, pts in edge_of.items():  # the inside vertices by the rim onto it, on the ball: the lid's edge runs
            q = min(pts, key=lambda t: (t - hv.co).length)  # along the outline, not zigzagging round its vertices
            me.vertices[hv.index].co = c + (q - c).normalized() * R
        U3, L3 = (e['U3'], e['L3']) if EYE_FROM[s_] == s_ else (mirror(EYE[EYE_FROM[s_]]['U3']), mirror(EYE[EYE_FROM[s_]]['L3']))
        ang = lambda q: math.atan2((q - c).z, (q - c).dot(FWD))  # noqa: E731
        e.update(pivot=c, R=R, h=(U3 - L3).length, deg=math.degrees(ang(U3) - ang(L3)), open=Vector(cen.tolist()))
        print('eye %s: r %.4f at %s, rim %d pts off the sphere %.4f..%.4f; %d sunk, %d lids lifted (most %.4f)'
              % (s_, R, tuple(round(x, 3) for x in c), len(rim), L.min() - R, L.max() - R, sunk, lifted, worst))
    me.update()


fit_eyes()
BLINK_DEG = max(e['deg'] for e in EYE.values())
print('eyes: blink %.1f deg (l %.1f, r %.1f)' % (BLINK_DEG, EYE['l']['deg'], EYE['r']['deg']))
