def set_weights():
    """Transferred MPFB weights, then: no eye, lid or lip-corner bones (painted eyes, closed mouth); the upper lids
    from lid_weight; the jaw from jaw_weight where it has a say; 'head' takes what is left. At most 4 bones."""
    vg = head.vertex_groups
    names = [g.name for g in vg]
    for v in head.data.vertices:
        w = {names[g.group]: g.weight for g in v.groups if g.weight > 0}
        tot = sum(w.values()) or 1.0
        w = {k: x / tot for k, x in w.items() if not k.startswith(('eye_', 'lid_', 'lip_corner_'))}
        if JAW[v.index] is not None:
            w['jaw'] = max(w.get('jaw', 0.0), JAW[v.index]) if JAW[v.index] > 0 else 0.0
        for side in EYE:
            if LIDS[side][v.index] > 0:
                w['lid_upper_' + side] = LIDS[side][v.index]
        rest = sum(x for k, x in w.items() if k != 'head')
        if rest > 1:
            w = {k: x / rest for k, x in w.items() if k != 'head'}
        else:
            w['head'] = 1 - rest
        w = dict(sorted(w.items(), key=lambda t: -t[1])[:4])
        tot = sum(w.values())
        for g in list(v.groups):
            vg[g.group].remove([v.index])
        for k, x in w.items():
            if x / tot > 1e-4:
                vg[k].add([v.index], x / tot, 'REPLACE')



def smoothstep(x, a, b):
    t = min(1.0, max(0.0, (x - a) / (b - a)))
    return t * t * (3 - 2 * t)


def neck_weights():
    """The turn of the head spread along the neck: under the collar the neck goes with the chest (spine_03), up the
    tube it passes from neck_01 to head over NECK_TWIST_ZS; whatever is outside the tube (the beard, jaw, face) is all
    head - transferred from the body, the neck/head border ran along the beard's underside and sheared it when the
    head turned."""
    vg = head.vertex_groups
    names = [g.name for g in vg]
    ax = Vector(sc['uniform']['NECK_AXIS'])
    ax.y += head_shape.NECK_C_DY  # the tube's own axis (neck_source)
    co = [v.co for v in head.data.vertices]
    # its girth over the straight stretch (decimated, a straight tube has few vertices: a thin slice missed most)
    sl = [c for c in co if NECK_Z0 + 0.003 < c.z < CHIN_Z - NECK_CUT - 0.012]
    rx = max(abs(c.x - ax.x) for c in sl); ry = max(abs(c.y - ax.y) for c in sl)
    for v in head.data.vertices:
        c = v.co
        d = math.hypot((c.x - ax.x) / rx, (c.y - ax.y) / ry)  # 1 on the neck tube
        up = max(smoothstep(c.z, *NECK_TWIST_ZS), smoothstep(d, 1.08, 1.35))
        chest = 1 - smoothstep(c.z, NECK_TWIST_ZS[0] - 0.02, NECK_TWIST_ZS[0])
        w = {names[g.group]: g.weight for g in v.groups if g.weight > 0}
        face = {k: x for k, x in w.items() if k not in ('head', 'neck_01', 'spine_03', 'spine_02', 'clavicle_l',
                                                         'clavicle_r')}
        fsum = sum(face.values())
        body = 1 - fsum
        new = dict(face)
        new['head'] = body * up
        new['neck_01'] = body * (1 - up) * (1 - chest)
        new['spine_03'] = body * (1 - up) * chest
        for g in list(v.groups):
            vg[g.group].remove([v.index])
        for k, x in new.items():
            if x > 1e-4:
                (vg.get(k) or vg.new(name=k)).add([v.index], x, 'REPLACE')
    print('neck weights: tube %.3f x %.3f, twist over z %.2f..%.2f' % (rx, ry, *NECK_TWIST_ZS))


set_weights()
neck_weights()

# ---------------------------------------------------------------- the body no longer carries the head
under = bpy.data.objects['BodyUnder']
ub = bmesh.new(); ub.from_mesh(under.data)
udl = ub.verts.layers.deform.active
ugn = [g.name for g in under.vertex_groups]
gone = [f for f in ub.faces if all(v.co.z > HEAD_Z + 0.01 and sum(w for g, w in v[udl].items() if ugn[g] in HEADISH) > 0.5
                                   for v in f.verts)]
bmesh.ops.delete(ub, geom=gone, context='FACES')
bmesh.ops.delete(ub, geom=[v for v in ub.verts if not v.link_faces], context='VERTS')
ub.to_mesh(under.data); ub.free()
# what shows of the body (the hands) in the face's skin colour
under.data.materials[0] = material('Body_Skin', None, 0.5, SKIN_LIN)

def eye_texture(iris, R, iris_r):
    """The eyeball's albedo, polar about its front: rows the angle from the front (0..180 deg), columns round it -
    pupil, the portrait's iris with fibres and a darker rim, the white going pink-grey towards the back."""
    res = 512
    v, u = np.meshgrid(np.linspace(0, 180, res), np.linspace(0, 2 * np.pi, res), indexing='ij')
    th_i = math.degrees(math.asin(min(iris_r / R, 0.95)))
    th_p = math.degrees(math.asin(min(iris_r * EYE_PUPIL / R, 0.9)))
    sclera = np.array(to_linear(EYE_SCLERA_RGB), np.float32)
    back = np.array(to_linear((0.62, 0.5, 0.47)), np.float32)
    rgb = sclera + (back - sclera) * np_smooth(v, 45, 90)[..., None]
    rgb = rgb * (1 - EYE_SCLERA_SHADE * np_smooth(v, th_i + 4, 42))[..., None]  # in the lids' shade towards the corners
    rgb = rgb * (1 - 0.12 * np_smooth(v, th_i + 8, th_i))[..., None]  # a little grey round the iris
    ir = np.array(to_linear(iris), np.float32)
    fib = 0.82 + 0.18 * np.sin(u * 47 + 3 * np.sin(u * 7)) * np.sin(u * 31)
    ring = 1 - 0.55 * np_smooth(v, th_i - 5, th_i - 1)       # the dark limbal rim
    collar = 1 + 0.25 * np.exp(-((v - th_p - 4) / 3) ** 2)    # the lighter collarette round the pupil
    iris_px = ir * (fib * ring * collar)[..., None]
    k = (1 - np_smooth(v, th_i - 0.5, th_i + 1.0))[..., None]
    rgb = rgb * (1 - k) + iris_px * k
    k = (1 - np_smooth(v, th_p - 0.7, th_p + 0.7))[..., None]
    rgb = rgb * (1 - k) + np.array([0.004, 0.004, 0.005], np.float32) * k
    rgb = np.clip(rgb, 0, 1)
    srgb = np.where(rgb <= 0.0031308, rgb * 12.92, 1.055 * np.power(rgb, 1 / 2.4) - 0.055)
    return mat_util.save('Eye_Albedo', srgb[::-1].astype(np.float32), EYE_TEX, 'sRGB')


def eyeballs():
    """Real eyeballs in the openings: spheres EYE_R round the lids' pivots (EYE_DEPTH behind the openings), their
    fronts along the portrait's view; skinned to eye_l / eye_r, so they can turn - build_pose.py turns them to the
    leader camera once the stance is set."""
    R = sum(e['R'] for e in EYE.values()) / len(EYE)
    iris_r = EYE_IRIS * sum(e['h'] for e in EYE.values()) / len(EYE)
    img = eye_texture(EYE_IRIS_RGB, R, iris_r)
    mat = mat_util.material('Eyes', img, None, None, rough=EYE_ROUGH)
    u_ax = FWD.cross(Vector((0, 0, 1))).normalized()
    w_ax = FWD.cross(u_ax)
    lat, lon = 24, 32
    co, faces, uvs, grp = [], [], [], []
    for s, e in EYE.items():
        c = e['pivot']
        base = len(co)
        for i in range(lat + 1):
            th = math.pi * i / lat
            for k in range(lon + 1):
                ph = 2 * math.pi * k / lon
                d = FWD * math.cos(th) + (u_ax * math.cos(ph) + w_ax * math.sin(ph)) * math.sin(th)
                co.append(c + d * e['R'])
                uvs.append((k / lon, 1 - i / lat))
                grp.append('eye_' + s)
        for i in range(lat):
            for k in range(lon):
                a = base + i * (lon + 1) + k
                faces.append((a, a + 1, a + lon + 2, a + lon + 1))
    me = bpy.data.meshes.new('Eyes')
    me.from_pydata([tuple(p) for p in co], [], faces)
    uvl = me.uv_layers.new(name='UVMap')
    for p in me.polygons:
        p.use_smooth = True
        for li in p.loop_indices:
            uvl.data[li].uv = uvs[me.loops[li].vertex_index]
    ob = bpy.data.objects.new('Eyes', me); sc.collection.objects.link(ob)
    ob['head_part'] = True
    me.materials.append(mat)
    for n in ('eye_l', 'eye_r'):
        g = ob.vertex_groups.new(name=n)
        g.add([i for i, x in enumerate(grp) if x == n], 1.0, 'REPLACE')
    ob.modifiers.new('Armature', 'ARMATURE').object = rig
    print('eyeballs: r %s, iris %.4f' % (', '.join('%.4f' % e['R'] for e in EYE.values()), iris_r))


eyeballs()
hd = dict(sc['head']); hd['BLINK_DEG'] = BLINK_DEG
# for build_pose.py's aim_eyes: each opening's middle (its rim's) and the eyeball's radius, rest pose
hd['EYE_OPEN'] = {s: list(e['open']) for s, e in EYE.items()}
hd['EYE_R'] = {s: e['R'] for s, e in EYE.items()}
sc['head'] = hd
print('head: %d verts, %d faces' % (len(head.data.vertices), len(head.data.polygons)))
bpy.ops.outliner.orphans_purge(do_recursive=True)
bpy.ops.wm.save_as_mainfile(filepath=OUT, compress=True)
print('saved', OUT, os.path.getsize(OUT))
